(async () => {
    const m = window.__mymechanics;
    await m.actions.ensureKernel();
    await m.actions.closeProject({ force: true });
    await m.actions.newDocument('part');
    const F = await import('/src/cad/features.js'); const S = await import('/src/cad/sketch.js'); const Rf = await import('/src/cad/refs.js');
    const part = m.active(); part.name = 'Bracket';
    const s = F.createFeature(part, 'sketch', { plane: { kind: 'std', name: 'top' }, ...S.createSketchGeometry() });
    S.addRectangle(s, 0, 0, 100, 50);
    part.features.push(s, F.createFeature(part, 'baseFlange', { sketch: s.id, thickness: 2, radius: 2, kFactor: 0.4 }));
    m.actions.change('op.edit', () => {});
    const body = m.actions.buildPart(part).body;
    const at = (e) => [e.startPoint, e.endPoint];
    const e1 = body.edges.find((e) => e.geomType === 'LINE' && at(e).every((p) => Math.abs(p.x - 100) < 1e-6 && Math.abs(p.z - 2) < 1e-6));
    const e2 = body.edges.find((e) => e.geomType === 'LINE' && at(e).every((p) => Math.abs(p.x) < 1e-6 && Math.abs(p.z) < 1e-6));
    const panel = body.faces.find((f) => f.geomType === 'PLANE' && Math.abs(f.center.z - 2) < 1e-6);
    m.actions.change('op.addFeature', () => {
      part.features.push(F.createFeature(part, 'edgeFlange', { edge: Rf.edgeSignature(e1), length: 20 }));
      part.features.push(F.createFeature(part, 'edgeFlange', { edge: Rf.edgeSignature(e2), length: 15 }));
      part.features.push(F.createFeature(part, 'crossBreak', { face: Rf.faceSignature(panel) }));
    });
    await new Promise((r) => setTimeout(r, 300));
    return String(m.actions.buildPart(part).result.sheet.bends.length);
  })()

