(async () => {
    const m = window.__mymechanics; const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    const d = m.active();
    // Each placement re-renders the sheet: find its SVG again for every click.
    const click = async (kind, fx, fy) => {
      await m.run(`ann:${kind}`);
      const svg = document.querySelector('#drawing-host svg');
      const box = svg.getBoundingClientRect();
      svg.dispatchEvent(new MouseEvent('click', { bubbles: true, clientX: box.left + box.width * fx, clientY: box.top + box.height * fy }));
      await sleep(250);
      return d.annotations.at(-1);
    };
    const c = await click('cloud', 0.3, 0.7); const dt = await click('datumTarget', 0.5, 0.7); const h = await click('hatch', 0.7, 0.7);
    await sleep(200);
    const host = document.querySelector('#drawing-host svg');
    const shown = ['ann-cloud', 'ann-datumTarget', 'ann-hatch'].map((k) => host.querySelectorAll(`.${k}`).length > 0);
    // Edit the cloud's width through its field in the drawing panel.
    const field = document.querySelector(`[data-ann="${c.id}:w"]`);
    if (field) { field.value = '80'; field.dispatchEvent(new Event('change', { bubbles: true })); }
    await sleep(200);
    const cloud = m.active().annotations.find((x) => x.id === c.id);
    return `${c.kind} ${dt.kind} ${h.kind} ${shown.join(',')} ${field ? cloud.w : 'nofield'}`;
  })()

